for p,h in hashes.items():assert hashlib.sha256((site/p).read_bytes()).hexdigest()==h,p
old=json.loads((b/'enrichment-before.json').read_text());new=json.loads((site/'data/writer-enrichment.json').read_text())
for k,v in old.items():assert new[k]==v,k
for i in [322,317,263,256,252]:
 d=json.loads((root/f'kb/research/writers/enrichment/{i}.json').read_text());assert d['reader_draft']==new[str(i)]
 page=(site/f'poet-{i}.html').read_text()
 for s in new[str(i)]['sections']:
  for p in s['paragraphs']:assert html.escape(p) in page,(i,p)
r=dict(batch='research-045',status='verified',independent=False,writer_ids=[322,317,263,256,252],reader_drafts=5,externally_corroborated=4,source_limited=[322],checks=dict(public_build='passed',author_pages='PASS',editions='PASS',preserved_source_files=len(hashes),existing_narratives_preserved=len(old),rendered_narratives=5,browser_visual='Not repeated; prose/data only, approved renderer unchanged.'),limitations=['Independent author/editor review pending.','322 literary narrative remains source-limited; expanded Choudhary name not confirmed.','317 official Fulbright record opened; Ravenshaw index corroborated, direct timeout recorded.','263 festival report read through indexed evidence; empty captured works list preserved, canonical poem links unchanged.','256/366 duplicate captured identity noted; shared biography and book card consistent, no source records merged.','252 author-owned catalogue opened; individual book subpage failures and changing historical counts recorded.'],resume='research-046',publication='No deployment or push.')
(b/'review.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n')
p=root/'kb/research/writers/enrichment-batches.json';d=json.loads(p.read_text())
for item in d['batches']:
 if item['id']==r['batch']:item['verification']='passed'
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n');print(r)
